TR = {en: (hi, ta) for en, hi, ta in _ROWS}


def tr(lang, s, **kw):
    t = s
    if lang in ("hi", "ta") and s in TR:
        t = TR[s][0 if lang == "hi" else 1]
    return t.format(**kw) if kw else t
